namespace SirketMotoru.Isletim;

public static class SirketYonetimHtml
{
    public const string Icerik = """
<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>Şirket Yönetim Merkezi v2</title>
<style>
:root{color-scheme:dark;--bg:#050914;--panel:#0b1424;--panel2:#101d31;--line:#243754;--text:#eef5ff;--muted:#91a6c2;--green:#45e2a2;--blue:#65a9ff;--red:#ff6d7e;--yellow:#ffd166;--purple:#b68cff;--shadow:0 18px 50px #0007}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 10% 0,#10284b 0,transparent 35%),radial-gradient(circle at 90% 0,#24174d 0,transparent 30%),var(--bg);color:var(--text);font-family:Inter,Segoe UI,Arial,sans-serif}body{padding:14px}button,input,select{font:inherit}.shell{max-width:1900px;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:14px 16px;border:1px solid var(--line);border-radius:17px;background:#091424eb;box-shadow:var(--shadow);position:sticky;top:8px;z-index:30;backdrop-filter:blur(14px)}.brand{font-size:18px;font-weight:950;letter-spacing:.04em}.brand small{display:block;margin-top:4px;color:var(--muted);font-size:10px;font-weight:500;letter-spacing:0}.status{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}.pill{border:1px solid var(--line);border-radius:999px;padding:7px 10px;color:var(--muted);font-size:10px;background:#0a1628}.pill b{color:var(--text)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--red);margin-right:6px}.dot.ok{background:var(--green);box-shadow:0 0 12px var(--green)}.hidden{display:none!important}.login{max-width:460px;margin:11vh auto;background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:22px;box-shadow:var(--shadow)}.login h1{margin-top:0}.notice{padding:10px 12px;border:1px solid var(--line);border-radius:10px;color:var(--muted);margin-top:10px}.notice.good{color:var(--green);border-color:#25634d}.notice.bad{color:var(--red);border-color:#763443}.banner{border:1px solid #6b592c;background:#211d12;color:var(--yellow);border-radius:12px;padding:11px;margin:13px 0}.metrics{display:grid;grid-template-columns:repeat(8,minmax(125px,1fr));gap:9px;margin:12px 0}.metric{background:linear-gradient(180deg,#101d31,#091423);border:1px solid var(--line);border-radius:13px;padding:11px;min-width:0}.metric span{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.08em}.metric b{display:block;margin-top:6px;font-size:17px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}.tab,button{cursor:pointer;border:1px solid transparent;border-radius:9px;padding:9px 12px;background:var(--green);color:#032018;font-weight:800}.tab{background:#0a1628;color:var(--muted);border-color:var(--line);border-radius:999px}.tab.active{background:linear-gradient(135deg,var(--green),var(--blue));color:#04141d;border-color:transparent}.secondary{background:#203653;color:var(--text)}.danger{background:var(--red);color:white}.small{font-size:10px;padding:7px 9px}.full{width:100%;margin-top:10px}button:disabled{opacity:.42;cursor:not-allowed}.page{display:none}.page.active{display:block}.card{background:linear-gradient(180deg,#101b2eeb,#08101deb);border:1px solid var(--line);border-radius:15px;padding:13px;box-shadow:var(--shadow)}.stack{display:grid;gap:11px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.item{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:11px;min-width:0}.item h3{margin:0 0 5px;font-size:14px}.item p{margin:4px 0;color:var(--muted);font-size:11px}.row{display:flex;justify-content:space-between;align-items:center;gap:9px}.tags{display:flex;gap:5px;flex-wrap:wrap;margin:7px 0}.tag{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 7px;color:var(--muted);font-size:9px}.tag.good{color:var(--green);border-color:#28634f}.tag.bad{color:var(--red);border-color:#743746}.tag.warn{color:var(--yellow);border-color:#6d592b}.sectiontitle{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}.sectiontitle h2{font-size:15px;margin:0}.sub{font-size:9px;color:var(--muted)}label{display:block;color:var(--muted);font-size:10px}input,select{display:block;width:100%;margin-top:4px;padding:9px;border:1px solid var(--line);border-radius:9px;background:#06111f;color:var(--text);outline:none}input:focus,select:focus{border-color:var(--blue);box-shadow:0 0 0 3px #65a9ff20}.formrow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;align-items:end;margin-top:9px}.formrow.three{grid-template-columns:repeat(3,minmax(0,1fr))}.tablewrap{overflow:auto;max-height:680px}table{width:100%;border-collapse:collapse;min-width:980px;font-size:10px}th{position:sticky;top:0;background:#101c30;color:var(--muted);text-align:left;font-size:9px;text-transform:uppercase;letter-spacing:.07em;padding:9px;border-bottom:1px solid var(--line);z-index:2}td{padding:9px;border-bottom:1px solid #1b2a41;vertical-align:top}td input{min-width:105px}.good{color:var(--green)}.bad{color:var(--red)}.warn{color:var(--yellow)}.tx{display:grid;grid-template-columns:70px 120px 1fr auto;gap:8px;padding:7px 0;border-bottom:1px solid var(--line);font-size:10px}.positive{color:var(--green)}.negative{color:var(--red)}.empty{color:var(--muted);padding:20px;text-align:center}.busybar{position:fixed;left:0;right:0;top:0;height:3px;background:linear-gradient(90deg,var(--green),var(--blue),var(--purple));transform:scaleX(0);transform-origin:left;transition:.18s;z-index:100}.busybar.on{transform:scaleX(1)}#toast{position:fixed;right:16px;bottom:16px;max-width:460px;background:#10243b;border:1px solid var(--line);border-radius:11px;padding:12px;z-index:80;box-shadow:var(--shadow)}.editing{color:var(--yellow)}@media(max-width:1400px){.metrics{grid-template-columns:repeat(4,1fr)}.grid4{grid-template-columns:repeat(2,1fr)}}@media(max-width:900px){body{padding:7px}.top{position:static;align-items:flex-start;flex-direction:column}.status{justify-content:flex-start}.metrics{grid-template-columns:repeat(2,1fr)}.grid,.grid3,.grid4,.formrow,.formrow.three{grid-template-columns:1fr}.tx{grid-template-columns:60px 1fr}.tx span:nth-child(3){grid-column:1/-1}}
</style>
</head>
<body>
<div id="busybar" class="busybar"></div>
<div class="shell">
<header class="top"><div class="brand">ŞİRKET YÖNETİM MERKEZİ v2<small>Canlı izleme · kararlı formlar · finans · yayın ve kapasite yönetimi</small></div><div class="status"><span class="pill"><i id="dot" class="dot"></i><b id="conn">BAĞLANTI YOK</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Son veri <b id="updated">—</b></span><span id="editState" class="pill">Formlar <b>HAZIR</b></span><button id="logout" class="secondary small hidden">Çıkış</button></div></header>
<section id="loginView" class="login"><h1>Şirket hesabına giriş</h1><p class="sub">Bu ekran kod üretmez. Sunucunun koddan ilan ettiği varlıkları ticari olarak yönetir.</p><label>Kullanıcı adı<input id="username" autocomplete="username"></label><label>Parola<input id="password" type="password" autocomplete="current-password"></label><button id="login" class="full">Giriş yap</button><div id="loginMsg" class="notice">Geçici giriş bilgileri motor konsolunda görünür.</div></section>
<main id="app" class="hidden"><div class="banner"><b>Kesin kural:</b> Hizmet, uygulama özelliği ve protokol kodu yalnız şirket sunucusunda yazılır. Burada fiyat, yayın, kapasite, yatırım, kredi ve sözleşme yönetilir.</div><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"><button class="tab active" data-tab="overview">Genel</button><button class="tab" data-tab="services">Hizmetler</button><button class="tab" data-tab="apps">Uygulamalar</button><button class="tab" data-tab="infra">Altyapı</button><button class="tab" data-tab="bank">Banka</button><button class="tab" data-tab="protocols">Protokoller</button><button class="tab" data-tab="contracts">Sözleşmeler</button><button class="tab" data-tab="security">Hesap</button></nav><section id="overview" class="page active stack"></section><section id="services" class="page card"></section><section id="apps" class="page stack"></section><section id="infra" class="page card"></section><section id="bank" class="page stack"></section><section id="protocols" class="page stack"></section><section id="contracts" class="page stack"></section><section id="security" class="page card"></section></main>
</div><div id="toast" class="hidden"></div>
<script>
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(n||0));
const num=n=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(n||0));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={data:null,pending:null,drafts:new Map(),timer:null,busy:false,loading:false,activeTab:'overview',toastTimer:null};
function draft(key,fallback){return S.drafts.has(key)?S.drafts.get(key):fallback??''}function field(key,value,type='number',attrs=''){return `<input data-key="${esc(key)}" type="${type}" value="${esc(draft(key,value))}" ${attrs}>`}function selectField(key,value,options){const selected=String(draft(key,value));return `<select data-key="${esc(key)}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===selected?'selected':''}>${esc(t)}</option>`).join('')}</select>`}
function toast(text,ok=true){const e=$('#toast');clearTimeout(S.toastTimer);e.textContent=text;e.className=ok?'notice good':'notice bad';e.classList.remove('hidden');S.toastTimer=setTimeout(()=>e.classList.add('hidden'),4500)}
function editing(){return S.busy||!!document.activeElement?.matches('input,select,textarea')}function showEditing(){const e=$('#editState');e.classList.toggle('editing',editing());e.innerHTML=`Formlar <b>${editing()?'KORUNUYOR':'HAZIR'}</b>`}
async function request(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await r.json()}catch{data={basarili:false,aciklama:'Sunucu yanıtı okunamadı.'}}if(!r.ok||data.basarili===false)throw new Error(data.aciklama||`HTTP ${r.status}`);return data}
async function login(){try{const result=await request('/api/giris',{kullaniciAdi:$('#username').value,parola:$('#password').value});$('#loginView').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');toast(result.aciklama||'Giriş başarılı.');await refresh(true);startPolling()}catch(e){$('#loginMsg').textContent=e.message;$('#loginMsg').className='notice bad'}}
async function logout(){try{await request('/api/cikis',{})}catch{}clearInterval(S.timer);location.reload()}
function startPolling(){clearInterval(S.timer);S.timer=setInterval(()=>refresh(false),900)}
async function refresh(force=false){if(S.loading)return;S.loading=true;try{const data=await request('/api/durum');S.data=data;$('#dot').classList.add('ok');$('#conn').textContent='MOTORA BAĞLI';$('#tick').textContent=data.tickNumarasi??0;$('#updated').textContent=new Date().toLocaleTimeString('tr-TR');renderMetrics(data);if(force||!editing()){S.pending=null;renderAll(data)}else S.pending=data}catch(e){$('#dot').classList.remove('ok');$('#conn').textContent='BAĞLANTI HATASI';if(String(e.message).includes('Oturum')){clearInterval(S.timer);location.reload()}}finally{S.loading=false;showEditing()}}
function renderMetrics(data){const s=data.sirket||{},i=data.isletim||{};$('#metrics').innerHTML=[['Kasa',money(s.kasa)],['Şirket değeri',money(companyValue(data))],['Aktif kullanıcı',num(i.toplamAboneSayisi)],['Toplam borç',money(i.toplamBorc)],['Kod kalitesi',num(s.kodKalitesiPuani)],['Performans',num(s.performansPuani)],['Güvenlik',num(s.guvenlikPuani)],['Kredi notu',num(i.krediNotu)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function companyValue(data){const s=data.sirket||{},i=data.isletim||{},k=data.kodTabanliYayinlar||{},products=i.urunler||[],services=k.hizmetler||s.hizmetler||[],protocols=k.protokoller||[],contracts=i.sozlesmeler||[],invest=Object.values(i.yatirimSeviyeleri||{}).reduce((a,b)=>a+Number(b||0),0),users=products.reduce((a,p)=>a+Number(p.aktifKullaniciSayisi||0),0),capacity=products.reduce((a,p)=>a+Number(p.kullaniciKapasitesi||0),0)+services.reduce((a,h)=>a+Number(h.azamiEszamanliIs||0),0)*50,productProfit=products.reduce((a,p)=>a+Math.max(0,Number(p.toplamGelir||0)-Number(p.toplamGider||0)),0),history=Number(s.tamamlananIsSayisi||0)*30+Math.max(0,Number(s.netGelir||0))*0.08,quality=(Number(s.kodKalitesiPuani||0)+Number(s.performansPuani||0)+Number(s.guvenlikPuani||0)+Number(s.itibarPuani||0)+Number(s.guvenilirlikPuani||0)+Number(s.ortalamaMusteriMemnuniyeti||0))*180,ecosystem=Number(i.ekosistemPuani||0)*300+protocols.filter(p=>p.piyasada).length*9000+services.filter(h=>h.aktif).length*1200,contractsValue=contracts.reduce((a,c)=>a+(c.aktif?Number(c.tickOdemesi||0)*Math.max(1,Number(c.bitisTicki||0)-Number(data.tickNumarasi||0)):Number(c.basariliTickSayisi||0)*80)-Number(c.ihlalSayisi||0)*500,0),cash=Math.max(0,Number(s.kasa||0))*0.15,debt=Number(i.toplamBorc||0)*1.15+Number(i.odenemeyenGider||0)*1.5+Number(i.temerrutSayisi||0)*5000;return Math.max(0,cash+users*55+capacity*4+productProfit*7+history+quality+ecosystem+contractsValue+invest*3500-debt)}
function renderAll(data){renderOverview(data);renderServices(data.kodTabanliYayinlar?.hizmetler||[]);renderApps(data.kodTabanliYayinlar?.uygulamalar||[],data.isletim?.urunler||[]);renderInfra(data.yatirimMagazasi||[]);renderBank(data.krediPaketleri||[],data.isletim?.krediler||[]);renderProtocols(data.kodTabanliYayinlar?.protokoller||[],data.protokoller||[]);renderContracts(data.sozlesmeTeklifleri||[],data.isletim?.sozlesmeler||[]);renderSecurity(data)}
function renderOverview(data){const s=data.sirket||{},i=data.isletim||{},events=(data.piyasaOlaylari||[]).map(o=>`<div class="item"><b>${esc(o.baslik)}</b><p>${esc(o.aciklama)}</p><div class="tags"><span class="tag warn">Tick ${o.baslangicTicki}-${o.bitisTicki}</span><span class="tag">Talep ×${num(o.talepCarpani)}</span><span class="tag">Gider ×${num(o.giderCarpani)}</span></div></div>`).join('')||'<div class="empty">Aktif piyasa olayı yok.</div>',tx=(i.sonIslemler||[]).slice(0,30).map(x=>`<div class="tx"><span>T${x.tickNumarasi}</span><span>${esc(x.islemTuru)}</span><span>${esc(x.aciklama)}</span><b class="${Number(x.tutar)>=0?'positive':'negative'}">${money(x.tutar)}</b></div>`).join('')||'<div class="empty">İşlem kaydı yok.</div>';$('#overview').innerHTML=`<div class="grid"><div class="card"><div class="sectiontitle"><h2>Şirket durumu</h2><span class="tag ${s.bagliMi?'good':'bad'}">${s.bagliMi?'SUNUCU BAĞLI':'SUNUCU KAPALI'}</span></div><div class="grid4">${[['Şirket değeri',money(companyValue(data))],['Ekosistem',num(i.ekosistemPuani)],['İtibar',num(s.itibarPuani)],['Güvenilirlik',num(s.guvenilirlikPuani)],['Memnuniyet',num(s.ortalamaMusteriMemnuniyeti)],['Abonelik geliri',money(i.toplamAbonelikGeliri)],['Ürün geliri',money(i.toplamUrunGeliri)],['Yatırım harcaması',money(i.toplamYatirimHarcamasi)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div><div class="card"><div class="sectiontitle"><h2>Piyasa olayları</h2></div>${events}</div></div><div class="card"><div class="sectiontitle"><h2>Son şirket işlemleri</h2></div>${tx}</div>`}
function renderServices(list){$('#services').innerHTML=`<div class="sectiontitle"><div><h2>Sunucunun ilan ettiği hizmetler</h2><div class="sub">Fiyat ve ticari aktiflik yönetilir; kod burada değişmez.</div></div><span class="tag">${list.length} hizmet</span></div><div class="tablewrap"><table><thead><tr><th>Hizmet</th><th>Sürüm</th><th>Fiyat</th><th>Kapasite</th><th>Uygulama bağı</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>${list.map(h=>{const id=`${h.hizmetKimligi}@${h.hizmetSurumu}`,key=`service:${id}:price`;return `<tr><td><b>${esc(h.hizmetKimligi)}</b></td><td>${esc(h.hizmetSurumu)}</td><td>${field(key,h.birimFiyat,'number','min="0.01" step="0.01"')}</td><td>${num(h.azamiEszamanliIs)}</td><td>${h.uygulamalardaKullaniliyor?'<span class="tag good">KULLANILIYOR</span>':'-'}</td><td><span class="tag ${h.aktif?'good':'bad'}">${h.aktif?'AKTİF':'PASİF'}</span></td><td><button class="small" data-action="service-price" data-id="${esc(id)}">Fiyatı kaydet</button> <button class="small ${h.aktif?'danger':'secondary'}" data-action="service-toggle" data-id="${esc(id)}">${h.aktif?'Pasife al':'Aktife al'}</button></td></tr>`}).join('')}</tbody></table></div>`}
function renderApps(apps,products){const byId=new Map(products.map(p=>[p.urunKimligi,p]));$('#apps').innerHTML=`<div class="card"><div class="sectiontitle"><div><h2>Kodlanan uygulamalar</h2><div class="sub">Yalnız standarttan geçen manifestler ticari yayına açılır.</div></div><span class="tag">${apps.length} manifest</span></div>${apps.length?apps.map(x=>appCard(x,byId)).join(''):'<div class="empty">Uygulama manifesti yok.</div>'}</div><div class="card"><div class="sectiontitle"><h2>Piyasadaki uygulamalar</h2><span class="tag">${products.length} ürün</span></div>${products.length?products.map(productCard).join(''):'<div class="empty">Piyasaya açılmış uygulama yok.</div>'}</div>`}
function appCard(x,byId){const a=x.uygulama||{},d=x.dogrulama||{},id=a.uygulamaKimligi,features=(a.ozellikler||[]).map(o=>`<span class="tag ${o.zorunlu?'good':''}">${esc(o.ozellikKimligi)} → ${esc(o.hizmetKimligi)}</span>`).join(''),errors=(d.hatalar||[]).map(e=>`<p class="negative">• ${esc(e)}</p>`).join('');return `<div class="item" style="margin-bottom:9px"><div class="row"><div><h3>${esc(a.uygulamaAdi)} <span class="tag">v${esc(a.surum)}</span></h3><p>${esc(a.aciklama)}</p></div><span class="tag ${d.gecerli?'good':'bad'}">${d.gecerli?'STANDARDI GEÇTİ':'EKSİK KOD'}</span></div><div class="tags">${features}</div>${errors}${x.piyasada?`<div class="notice good">Piyasada · ${esc(x.urunKimligi)}</div>`:`<div class="formrow"><label>Model${selectField(`app:${id}:model`,'abonelik',[['abonelik','Abonelik'],['kullanim','Kullanım'],['freemium','Freemium'],['lisans','Lisans']])}</label><label>Abonelik${field(`app:${id}:sub`,25,'number','min="0" step="0.01"')}</label><label>Kullanım${field(`app:${id}:use`,0,'number','min="0" step="0.0001"')}</label><button data-action="app-publish" data-id="${esc(id)}" ${!d.gecerli||!x.sunucuBagli?'disabled':''}>Piyasaya aç</button></div>`}</div>`}
function productCard(p){const id=p.urunKimligi;return `<div class="item" style="margin-bottom:9px"><div class="row"><div><h3>${esc(p.urunAdi)}</h3><p>${esc(p.kategori)} · ${num(p.aktifKullaniciSayisi)}/${num(p.kullaniciKapasitesi)} kullanıcı · Gelir ${money(p.toplamGelir)}</p></div><span class="tag ${p.aktif?'good':'bad'}">${p.aktif?'AKTİF':'DURDURULDU'}</span></div><div class="formrow"><label>Abonelik${field(`product:${id}:sub`,p.abonelikUcreti,'number','min="0" step="0.01"')}</label><label>Kullanım${field(`product:${id}:use`,p.kullanimBasinaUcret,'number','min="0" step="0.0001"')}</label><label>Kapasite ekle${field(`product:${id}:cap`,100,'number','min="100" step="100"')}</label><div><button class="small" data-action="product-save" data-id="${esc(id)}">Kaydet</button> <button class="small secondary" data-action="product-capacity" data-id="${esc(id)}">Kapasite al</button> <button class="small ${p.aktif?'danger':'secondary'}" data-action="product-toggle" data-id="${esc(id)}">${p.aktif?'Durdur':'Yayına al'}</button></div></div></div>`}
function renderInfra(list){$('#infra').innerHTML=`<div class="sectiontitle"><div><h2>Altyapı ve departman yatırımları</h2><div class="sub">Para kapasite ve işletme kabiliyeti alır; yanlış kodu düzeltmez.</div></div></div><div class="grid4">${list.map(x=>`<div class="item"><h3>${esc(x.ad)}</h3><p>${esc(x.aciklama)}</p><div class="row"><span>Seviye ${x.seviye}/${x.azamiSeviye}</span><b>${money(x.sonrakiMaliyet)}</b></div><button class="full" data-action="investment-buy" data-id="${esc(x.yatirimTuru)}" ${x.seviye>=x.azamiSeviye?'disabled':''}>Satın al</button></div>`).join('')}</div>`}
function renderBank(packs,loans){$('#bank').innerHTML=`<div class="card"><div class="sectiontitle"><h2>Kredi paketleri</h2><span class="tag warn">Taksitler ticklerde kesilir</span></div><div class="grid">${packs.map(p=>`<div class="item"><h3>${esc(p.ad)}</h3><p>${money(p.asgariTutar)}–${money(p.azamiTutar)} · Not ≥ ${p.asgariKrediNotu} · ${p.taksitSayisi} taksit</p><label>Tutar${field(`loan:${p.krediTuru}:amount`,p.asgariTutar,'number',`min="${p.asgariTutar}" max="${p.azamiTutar}" step="100"`)}</label><button class="full" data-action="loan-take" data-id="${esc(p.krediTuru)}">Kredi çek</button></div>`).join('')}</div></div><div class="card"><div class="sectiontitle"><h2>Krediler</h2></div>${loans.length?loans.map(l=>`<div class="item" style="margin-bottom:8px"><div class="row"><b>${esc(l.krediTuru)}</b><span class="${l.aktif?'warn':'good'}">${l.aktif?'AKTİF':'KAPANDI'}</span></div><p>Kalan ${money(l.kalanBorc)} · Taksit ${money(l.taksitTutari)} · ${l.kalanTaksit} ödeme · Gecikme ${l.gecikmeSayisi}</p></div>`).join(''):'<div class="empty">Kredi kaydı yok.</div>'}</div>`}
function renderProtocols(declared,market){$('#protocols').innerHTML=`<div class="card"><div class="sectiontitle"><h2>Kodlanan özel protokoller</h2><span class="tag">${declared.length}</span></div>${declared.length?declared.map(x=>{const p=x.protokol||{},id=`${p.protokolKimligi}@${p.surum}`;return `<div class="item" style="margin-bottom:9px"><div class="row"><div><h3>${esc(p.protokolAdi)} <span class="tag">v${esc(p.surum)}</span></h3><p>${esc(p.aciklama)}</p></div><span class="tag ${x.gecerli?'good':'bad'}">${x.gecerli?'KOD UYUMLU':'HİZMET EKSİK'}</span></div><div class="tags">${(p.yetkinlikler||[]).map(y=>`<span class="tag">${esc(y.yetkinlikKimligi)} → ${esc(y.hizmetKimligi)}</span>`).join('')}</div>${x.piyasada?`<div class="notice good">Piyasada · ${esc(x.piyasaProtokolKimligi)}</div>`:`<div class="formrow"><label>Lisans${selectField(`protocol:${id}:license`,'acik',[['acik','Açık'],['tek-seferlik','Tek seferlik'],['abonelik','Abonelik'],['karma','Karma']])}</label><label>Benimseme${field(`protocol:${id}:adopt`,0,'number','min="0" step="1"')}</label><label>Tick lisansı${field(`protocol:${id}:tick`,0,'number','min="0" step="1"')}</label><button data-action="protocol-publish" data-id="${esc(id)}" ${!x.gecerli?'disabled':''}>Piyasaya aç</button></div>`}</div>`}).join(''):'<div class="empty">Protokol manifesti yok.</div>'}</div><div class="card"><div class="sectiontitle"><h2>Protokol piyasası</h2></div>${market.length?market.map(p=>`<div class="item" style="margin-bottom:8px"><div class="row"><div><b>${esc(p.protokolAdi)} v${esc(p.surum)}</b><p>${esc(p.aciklama)}</p></div><button class="small" data-action="protocol-adopt" data-id="${esc(p.protokolKimligi)}">Benimse</button></div><div class="tags"><span class="tag">${money(p.benimsemeBedeli)}</span><span class="tag">${money(p.tickLisansBedeli)}/tick</span><span class="tag">${num((p.benimseyenSirketler||[]).length)} şirket</span></div></div>`).join(''):'<div class="empty">Piyasada protokol yok.</div>'}</div>`}
function renderContracts(offers,active){$('#contracts').innerHTML=`<div class="card"><div class="sectiontitle"><h2>Açık SLA teklifleri</h2><span class="tag">${offers.length}</span></div>${offers.length?offers.map(o=>`<div class="item" style="margin-bottom:8px"><div class="row"><div><h3>${esc(o.baslik)}</h3><p>${esc(o.kategori)} · ${o.sureTick} tick</p></div><button class="small" data-action="contract-accept" data-id="${esc(o.teklifKimligi)}">Kabul et</button></div><div class="tags"><span class="tag good">${money(o.tickOdemesi)}/tick</span><span class="tag bad">${money(o.ihlalCezasi)} ceza</span><span class="tag">K ${o.asgariKalite}</span><span class="tag">P ${o.asgariPerformans}</span><span class="tag">G ${o.asgariGuvenlik}</span><span class="tag">Kap. ${o.gerekliKapasite}</span></div></div>`).join(''):'<div class="empty">Açık teklif yok.</div>'}</div><div class="card"><div class="sectiontitle"><h2>Sözleşme geçmişi</h2></div>${active.length?active.map(s=>`<div class="item" style="margin-bottom:8px"><div class="row"><b>${esc(s.baslik)}</b><span class="tag ${s.aktif?'good':'bad'}">${s.aktif?'AKTİF':'BİTTİ'}</span></div><p>Tick ${s.baslangicTicki}-${s.bitisTicki} · Başarılı ${s.basariliTickSayisi} · İhlal ${s.ihlalSayisi}</p></div>`).join(''):'<div class="empty">Sözleşme yok.</div>'}</div>`}
function renderSecurity(data){const s=data.sirket||{};$('#security').innerHTML=`<div class="sectiontitle"><h2>Hesap ve güvenlik</h2></div><div class="grid"><div class="item"><h3>Parola değiştir</h3><label>Mevcut parola${field('account:old','', 'password','autocomplete="current-password"')}</label><label>Yeni parola${field('account:new','', 'password','autocomplete="new-password"')}</label><button class="full" data-action="change-pass">Parolayı değiştir</button></div><div class="item"><h3>Şirket güvenlik özeti</h3><p>Güvenlik puanı: <b>${num(s.guvenlikPuani)}</b></p><p>Kod kalitesi: <b>${num(s.kodKalitesiPuani)}</b></p><p>Performans: <b>${num(s.performansPuani)}</b></p><p>Bu hesap yalnız kendi şirketinin ticari ayarlarını değiştirebilir.</p></div></div>`}
function getValue(key){const el=document.querySelector(`[data-key="${CSS.escape(key)}"]`);return el?el.value:draft(key,'')}function numberValue(key){const value=Number(getValue(key));if(!Number.isFinite(value))throw new Error('Sayısal alan geçersiz.');return value}function clearPrefix(prefix){for(const key of [...S.drafts.keys()])if(key.startsWith(prefix))S.drafts.delete(key)}
function findService(id){return (S.data?.kodTabanliYayinlar?.hizmetler||[]).find(h=>`${h.hizmetKimligi}@${h.hizmetSurumu}`===id)}function findApp(id){return (S.data?.kodTabanliYayinlar?.uygulamalar||[]).find(x=>x.uygulama?.uygulamaKimligi===id)}function findProduct(id){return (S.data?.isletim?.urunler||[]).find(x=>x.urunKimligi===id)}function findProtocol(id){return (S.data?.kodTabanliYayinlar?.protokoller||[]).find(x=>`${x.protokol?.protokolKimligi}@${x.protokol?.surum}`===id)}function findLoan(id){return (S.data?.krediPaketleri||[]).find(x=>x.krediTuru===id)}
async function runAction(button,work,clear=''){if(S.busy)return;S.busy=true;showEditing();$('#busybar').classList.add('on');const old=button.textContent;button.disabled=true;button.textContent='İşleniyor…';try{const result=await work();if(clear)clearPrefix(clear);toast(result.aciklama||'İşlem tamamlandı.');await refresh(true)}catch(e){toast(e.message,false)}finally{S.busy=false;button.disabled=false;button.textContent=old;$('#busybar').classList.remove('on');showEditing();if(S.pending&&!editing()){const p=S.pending;S.pending=null;renderAll(p)}}}
async function handleAction(button){const action=button.dataset.action,id=button.dataset.id||'';await runAction(button,async()=>{if(action==='service-price'){const h=findService(id);return request('/api/hizmet/fiyat',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,yeniFiyat:numberValue(`service:${id}:price`)})}if(action==='service-toggle'){const h=findService(id);return request('/api/hizmet/durum',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,aktif:!h.aktif})}if(action==='app-publish'){const x=findApp(id);return request('/api/uygulama/yayinla',{uygulamaKimligi:id,fiyatlandirmaModeli:getValue(`app:${id}:model`),abonelikUcreti:numberValue(`app:${id}:sub`),kullanimBasinaUcret:numberValue(`app:${id}:use`)})}if(action==='product-save'||action==='product-toggle'){const p=findProduct(id);return request('/api/uygulama/guncelle',{urunKimligi:id,abonelikUcreti:numberValue(`product:${id}:sub`),kullanimBasinaUcret:numberValue(`product:${id}:use`),aktif:action==='product-toggle'?!p.aktif:p.aktif})}if(action==='product-capacity')return request('/api/uygulama/kapasite',{urunKimligi:id,eklenecekKapasite:numberValue(`product:${id}:cap`)});if(action==='investment-buy')return request('/api/yatirim',{yatirimTuru:id});if(action==='loan-take')return request('/api/kredi',{krediTuru:id,tutar:numberValue(`loan:${id}:amount`)});if(action==='protocol-publish'){const x=findProtocol(id),p=x.protokol;return request('/api/protokol/yayinla',{protokolKimligi:p.protokolKimligi,surum:p.surum,lisansModeli:getValue(`protocol:${id}:license`),benimsemeBedeli:numberValue(`protocol:${id}:adopt`),tickLisansBedeli:numberValue(`protocol:${id}:tick`)})}if(action==='protocol-adopt')return request('/api/protokol/benimse',{protokolKimligi:id});if(action==='contract-accept')return request('/api/sozlesme/kabul',{teklifKimligi:id});if(action==='change-pass')return request('/api/parola',{eskiParola:getValue('account:old'),yeniParola:getValue('account:new')});throw new Error('Bilinmeyen işlem.')},action==='service-price'?`service:${id}:`:action.startsWith('app-')?`app:${id}:`:action.startsWith('product-')?`product:${id}:`:action==='loan-take'?`loan:${id}:`:action==='protocol-publish'?`protocol:${id}:`:action==='change-pass'?'account:':'')}
document.addEventListener('input',e=>{const key=e.target?.dataset?.key;if(key)S.drafts.set(key,e.target.value);showEditing()});document.addEventListener('change',e=>{const key=e.target?.dataset?.key;if(key)S.drafts.set(key,e.target.value)});document.addEventListener('focusin',showEditing);document.addEventListener('focusout',()=>setTimeout(()=>{showEditing();if(S.pending&&!editing()){const p=S.pending;S.pending=null;renderAll(p)}},180));document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){S.activeTab=tab.dataset.tab;$$('.tab').forEach(x=>x.classList.toggle('active',x===tab));$$('.page').forEach(x=>x.classList.toggle('active',x.id===S.activeTab));return}const action=e.target.closest('[data-action]');if(action)handleAction(action)});$('#login').addEventListener('click',login);$('#password').addEventListener('keydown',e=>{if(e.key==='Enter')login()});$('#logout').addEventListener('click',logout);request('/api/durum').then(()=>{$('#loginView').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');refresh(true);startPolling()}).catch(()=>{});
</script>
</body>
</html>
""";
}
